mapper.select:
SELECT
e.expense_id AS expenseId,
e.user_card_id AS userCardId,
cd.card_name AS cardName,
cd.card_type AS cardType,
e.category_id AS categoryId,
c.category_name AS categoryName,
e.merchant_name AS merchantName,
e.amount AS paymentAmount,
COALESCE(e.discount_amount, 0) AS discountAmount,
DATE_FORMAT(e.payment_date, '%Y-%m-%dT%H:%i:%s') AS paymentDate,
e.payment_status AS paymentStatus,
e.approval_status AS approvalStatus,
e.transaction_type AS transactionType,
e.region AS region,
e.input_type AS inputType
FROM expense e
JOIN user_card uc
ON e.user_card_id = uc.user_card_id
JOIN card cd
ON uc.card_id = cd.card_id
JOIN category c
ON e.category_id = c.category_id
WHERE e.member_id = #{userId}


    AND DATE_FORMAT(e.payment_date, '%Y-%m') = #{yearMonth}




    AND (
    e.category_id = #{categoryId}
    OR c.parent_category_id = #{categoryId}
    )



    AND e.user_card_id = #{userCardId}



    AND e.payment_status = #{paymentStatus}



    AND e.approval_status = #{approvalStatus}



    AND cd.card_type = #{cardType}



    AND e.region = #{region}



    AND e.transaction_type = #{transactionType}



    AND e.payment_date >= CONCAT(#{startDate}, ' 00:00:00')



    AND e.payment_date < DATE_ADD(#{endDate}, INTERVAL 1 DAY)



ORDER BY e.payment_date DESC, e.expense_id DESC



    LIMIT #{limit} OFFSET #{offset}
